// ─── File: LoadBalancerStrategiesDemo.java ───
// Round robin, least connections, and consistent hashing compared.
import java.util.*;
import java.util.logging.*;

public class LoadBalancerStrategiesDemo {
    private static final Logger log = Logger.getLogger("LB");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        List<Backend> pool = new ArrayList<>(List.of(
                new Backend("api-1"), new Backend("api-2"), new Backend("api-3")));

        log.info("=== ROUND ROBIN (uniform requests, equal instances) ===");
        RoundRobin rr = new RoundRobin(pool);
        for (int i = 1; i <= 4; i++) rr.pick("req-" + i);

        log.info("=== LEAST CONNECTIONS (variable request durations) ===");
        LeastConnections lc = new LeastConnections(pool);
        pool.get(0).setActive(5);   // api-1 is busy with long requests
        pool.get(1).setActive(1);
        pool.get(2).setActive(0);
        lc.pick("statement-big");   // should avoid busy api-1
        lc.pick("statement-small");

        log.info("=== CONSISTENT HASHING (cache nodes come and go) ===");
        ConsistentHashing ch2 = new ConsistentHashing(150);
        for (Backend b : pool) ch2.addNode(b.name());
        String[] keys = {"SAV2001", "CUR3001", "SAV2002", "CUR3002", "SAV2003"};
        Map<String, String> before = new LinkedHashMap<>();
        for (String k : keys) before.put(k, ch2.getNode(k));
        before.forEach((k, v) -> log.info(() -> "key " + k + " → " + v));
        log.info("--- add api-4: only a FEW keys should remap ---");
        ch2.addNode("api-4");
        int remapped = 0;
        for (String k : keys) {
            String now = ch2.getNode(k);
            if (!now.equals(before.get(k))) { remapped++; log.info(() -> "key " + k + " REMAPPED → " + now); }
        }
        int fRemapped = remapped;
        log.info(() -> "Remapped " + fRemapped + "/" + keys.length + " keys (plain modulo would remap most)");
    }
}

// ─── model/Backend.java ───
class Backend {
    private final String name;
    private int active = 0;
    Backend(String name) { this.name = name; }
    String name() { return name; }
    int active() { return active; }
    void setActive(int n) { active = n; }
    void inc() { active++; }
}

// ─── strategy/LoadBalancingStrategy.java ───
interface LoadBalancingStrategy {
    Backend pick(String requestKey);
}

// ─── strategy/RoundRobin.java ───
class RoundRobin implements LoadBalancingStrategy {
    private static final Logger log = Logger.getLogger("LB");
    private final List<Backend> pool;
    private int idx = 0;
    RoundRobin(List<Backend> pool) { this.pool = pool; }
    public Backend pick(String requestKey) {
        Backend b = pool.get(Math.floorMod(idx++, pool.size())); // floorMod: safe cycling
        log.info(() -> "RR " + requestKey + " → " + b.name());
        return b;
    }
}

// ─── strategy/LeastConnections.java ───
class LeastConnections implements LoadBalancingStrategy {
    private static final Logger log = Logger.getLogger("LB");
    private final List<Backend> pool;
    LeastConnections(List<Backend> pool) { this.pool = pool; }
    public Backend pick(String requestKey) {
        Backend chosen = pool.get(0);
        for (Backend b : pool) if (b.active() < chosen.active()) chosen = b;
        chosen.inc();
        Backend f = chosen;
        log.info(() -> "LC " + requestKey + " → " + f.name() + " (active=" + f.active() + ")");
        return chosen;
    }
}

// ─── strategy/ConsistentHashing.java ───
class ConsistentHashing implements LoadBalancingStrategy {
    private final int virtualNodes;
    private final TreeMap<Integer, String> ring = new TreeMap<>(); // hash → node name
    ConsistentHashing(int virtualNodes) { this.virtualNodes = virtualNodes; }
    void addNode(String node) {
        for (int i = 0; i < virtualNodes; i++) ring.put(hash(node + "#" + i), node);
    }
    void removeNode(String node) {
        for (int i = 0; i < virtualNodes; i++) ring.remove(hash(node + "#" + i));
    }
    String getNode(String key) {
        if (ring.isEmpty()) return null;
        int h = hash(key);
        Map.Entry<Integer, String> e = ring.ceilingEntry(h);  // next node clockwise
        if (e == null) e = ring.firstEntry();                 // wrap around the ring
        return e.getValue();
    }
    public Backend pick(String requestKey) { return new Backend(getNode(requestKey)); }
    private int hash(String s) { return s.hashCode() & 0x7fffffff; }
}

